                        moments(7*(k*9+j*3+i)+n)=moments(7*(i*9+j*3+k)+n+2)
                        moments(7*(i*9+j*3+k)+n+2)=temp
                     else if (n.eq.0.or.n.eq.2.or.n.eq.5) then
